  const RULE_TYPE_LABELS={max_consecutive:'أقصى حصص متتالية',max_daily:'أقصى حصص في اليوم',no_first:'منع الحصة الأولى',no_last:'منع الحصة الأخيرة',blocked_period:'منع حصة محددة',double_contiguous:'حصص مزدوجة متتالية دون فسحة'};
