  function updateRuleTargetOptions(){const scope=$('#ruleScope').value;let arr=[];if(scope==='department')arr=[...new Set(state.teachers.map(t=>t.department).filter(Boolean))].map(x=>({id:x,name:x}));if(scope==='teacher')arr=state.teachers;if(scope==='subject')arr=state.subjects;if(scope==='class')arr=state.classes;$('#ruleTarget').disabled=scope==='all';$('#ruleTarget').innerHTML=scope==='all'?'<option value="">الجميع</option>':options(arr,arr[0]?.id)}
  function repairDoubleAssignments(input){
    let working=clone(input);const assignments=state.assignments.filter(a=>doubleRuleApplies(a));
    for(const assignment of assignments){if(doubleAssignmentValid(assignment,working))continue;const lessons=working.filter(e=>e.assignmentId===assignment.id).sort((a,b)=>a.dayId.localeCompare(b.dayId)||Number(a.periodId)-Number(b.periodId));let fixed=false;
      for(const anchor of lessons){const mate=lessons.find(x=>x.id!==anchor.id);if(!mate)continue;for(const targetPeriod of [Number(anchor.periodId)-1,Number(anchor.periodId)+1]){if(targetPeriod<1||targetPeriod>slotsForDay(anchor.dayId).length||!consecutiveWithoutBreak(assignment.classId,anchor.periodId,targetPeriod,anchor.dayId))continue;const attempt=cascadePlace(working,mate.id,{dayId:anchor.dayId,periodId:targetPeriod},{depth:0,nodes:{count:0},visited:new Set(),protectedIds:new Set([anchor.id]),preferredById:{}});if(attempt&&doubleAssignmentValid(assignment,attempt.schedule)){working=attempt.schedule;fixed=true;break}}if(fixed)break}
      if(!fixed){outer:for(const d of activeDays())for(const p of slotsForDay(d.id).slice(0,-1)){if(!consecutiveWithoutBreak(assignment.classId,p,p+1,d.id))continue;const first=lessons[0],second=lessons[1];if(!first||!second)break outer;const a=cascadePlace(working,first.id,{dayId:d.id,periodId:p},{depth:0,nodes:{count:0},visited:new Set(),protectedIds:new Set([second.id]),preferredById:{}});if(!a)continue;const b=cascadePlace(a.schedule,second.id,{dayId:d.id,periodId:p+1},{depth:0,nodes:{count:0},visited:new Set(),protectedIds:new Set([first.id,...a.movedIds]),preferredById:{}});if(b&&doubleAssignmentValid(assignment,b.schedule)){working=b.schedule;fixed=true;break outer}}}
      if(!fixed)return null;
    }return working;
  }
  function repairRulePlacements(input){let working=clone(input),guard=0;while(guard++<Math.max(40,input.length)){const blocked=working.find(e=>placementConstraint(e));if(!blocked)return working;byId(working,blocked.id).locked=false;let resolved=null;for(const candidate of relocationCandidates(byId(working,blocked.id),working)){const attempt=cascadePlace(working,blocked.id,candidate,{depth:0,nodes:{count:0},visited:new Set(),protectedIds:new Set(),preferredById:{}});if(attempt){resolved=attempt;break}}if(!resolved)return null;working=resolved.schedule}return null}
  function ruleRepairEntryIds(issue,schedule){
    const rule=byId(state.rules,issue.ruleId),entries=(issue.entryIds||[issue.entryId]).map(id=>byId(schedule,id)).filter(e=>e&&!e.locked);if(!rule||rule.type!=='max_consecutive')return entries.map(e=>e.id);
    const sorted=entries.sort((a,b)=>Number(a.periodId)-Number(b.periodId)),runs=[];let run=[];for(const entry of sorted){if(run.length&&Number(entry.periodId)!==Number(run.at(-1).periodId)+1){if(run.length>Number(rule.value))runs.push(run);run=[]}run.push(entry)}if(run.length>Number(rule.value))runs.push(run);return runs.flatMap(group=>{const middle=group[Math.floor(group.length/2)];return [middle,...group.slice().reverse(),...group]}).map(e=>e.id).filter((id,index,all)=>all.indexOf(id)===index);
  }
  function contextualRuleScore(schedule){const issues=ruleAuditIssues(schedule);return {issues,score:issues.reduce((sum,item)=>sum+100+20*(Number(item.excess)||1),0)}}
  function repairContextualRules(input){
    let working=clone(input);for(let iteration=0;iteration<180;iteration++){const current=contextualRuleScore(working);if(!current.issues.length)return working;let accepted=null,acceptedScore=current.score;const ranked=current.issues.slice().sort((a,b)=>(Number(b.excess)||1)-(Number(a.excess)||1));
      for(const issue of ranked.slice(0,12)){for(const entryId of ruleRepairEntryIds(issue,working).slice(0,10)){const entry=byId(working,entryId);if(!entry)continue;for(const target of relocationCandidates(entry,working).slice(0,18)){const attempt=cascadePlace(working,entryId,target,{depth:0,nodes:{count:0},visited:new Set(),protectedIds:new Set(),preferredById:{}});if(!attempt)continue;const next=contextualRuleScore(attempt.schedule);if(next.score<acceptedScore){accepted=attempt.schedule;acceptedScore=next.score;if(!acceptedScore)break}}if(accepted)break}if(accepted)break}
      if(!accepted)return null;working=accepted;
    }return contextualRuleScore(working).score?null:working;
  }
  function regenerateForRules(before,title){
    for(let attempt=0;attempt<5;attempt++){
      let schedule=repairRulePlacements(before);if(schedule)schedule=repairContextualRules(schedule);if(schedule)schedule=repairDoubleAssignments(schedule);if(schedule)schedule=repairContextualRules(schedule);if(!schedule)continue;
      const audit=computeAudit(schedule);if(!audit.hard.length&&!audit.missing.length){state.schedule=schedule;return recordScheduleChange(before,state.schedule,title)}
    }
    const result=generateBest(false),audit=computeAudit(result.schedule);if(result.missing||audit.hard.length)return null;state.schedule=result.schedule;return recordScheduleChange(before,state.schedule,title)
  }
  function mutateRuleAndApply(mutator,title){const before=clone(state.schedule);snapshot(`قبل ${title}`,true);mutator();const batch=regenerateForRules(before,title);if(!batch)state.schedule=before;save(true);renderAll();renderRulesAndReservations();if(batch){showChangeReport(batch);toast('تم حفظ القاعدة وإعادة توزيع الحصص لتطبيقها دون تعارض.','success');return}const audit=computeAudit(),ruleIssues=audit.hard.filter(i=>i.type==='rule');if(ruleIssues.length){toast(`تم حفظ القاعدة وتفعيلها، لكنها تنتظر إعادة توزيع ${ruleIssues.length} مخالفة حالية. السبب الأول: ${ruleIssues[0].text}`);return}toast('تم حفظ حالة القاعدة، والجدول يطابق القواعد النشطة.','success')}
  function addRule(){const name=$('#ruleName').value.trim(),type=$('#ruleType').value,scope=$('#ruleScope').value,target=scope==='all'?'':$('#ruleTarget').value,value=Math.max(1,Number($('#ruleValue').value)||1);if(!name){toast('اكتب اسمًا واضحًا للقاعدة.','error');return}if(scope!=='all'&&!target){toast('اختر المستهدف الذي ستطبق عليه القاعدة.','error');return}mutateRuleAndApply(()=>state.rules.push({id:uid('rule'),name,type,scope,target,value,active:true}),`إضافة قاعدة «${name}»`);$('#ruleName').value=''}
  function applyRulesNow(){const before=clone(state.schedule);snapshot('قبل تطبيق القواعد',true);const batch=regenerateForRules(before,'تطبيق جميع القواعد النشطة');if(!batch)state.schedule=before;save(true);renderAll();if(batch){showChangeReport(batch);toast('تم تطبيق جميع القواعد النشطة وإعادة توزيع الحصص دون تعارض.','success');return}const audit=computeAudit(),ruleIssues=audit.hard.filter(i=>i.type==='rule'),missing=audit.missing.reduce((sum,item)=>sum+item.diff,0);if(ruleIssues.length||missing){toast(`القواعد ما زالت مفعّلة ومحفوظة، لكن لم نجد توزيعًا كاملًا الآن: ${ruleIssues.length} مخالفة و${missing} حصة ناقصة. خفف قاعدة شديدة أو افتح الحصص المقفلة ثم أعد المحاولة.`,'error');return}toast('الجدول يطابق جميع القواعد النشطة بالفعل.','success')}

  function renderReports(){
    const a=computeAudit();const totalMissing=a.missing.reduce((s,m)=>s+m.diff,0);const gaps=teacherGaps();const overload=state.teachers.filter(t=>state.schedule.filter(e=>e.teacherId===t.id).length>(Number(t.quota)||0)).length;
    $('#reportCards').innerHTML=`<div class="report-card ${a.hard.length?'bad':'ok'}"><small>التعارضات</small><strong>${a.hard.length}</strong></div><div class="report-card ${totalMissing?'warn':'ok'}"><small>الحصص الناقصة</small><strong>${totalMissing}</strong></div><div class="report-card ${a.warnings.length?'warn':'ok'}"><small>تنبيهات التوزيع</small><strong>${a.warnings.length}</strong></div><div class="report-card"><small>فراغات المعلّمين</small><strong>${gaps}</strong></div>`;
    $('#issuesList').innerHTML=a.issues.length?a.issues.map(i=>`<div class="issue ${i.severity==='warning'?'warning':i.severity==='info'?'info':''}" data-entry="${i.entryId||''}" data-assignment="${i.assignmentId||''}"><span class="issue-icon">${i.severity==='error'?'!':i.severity==='warning'?'△':'i'}</span><div><strong>${esc(i.text)}</strong><small>${esc(i.detail||'')}</small></div><button class="mini-btn">${i.assignmentId?'معالجة':'عرض'}</button></div>`).join(''):'<div class="empty-state"><div>✓</div><h3>لا توجد مشكلات</h3><p>الجدول اجتاز الفحص الحالي.</p></div>';
    $$('.issue',$('#issuesList')).forEach(el=>el.onclick=()=>{if(el.dataset.assignment){navigate('data');activeDataTab='assignments';$$('.tab',$('#dataTabs')).forEach(x=>x.classList.toggle('active',x.dataset.tab==='assignments'));renderData();const row=$(`[data-row-id="${el.dataset.assignment}"]`);row?.scrollIntoView({behavior:'smooth',block:'center'});row?.animate([{outline:'4px solid #c64242'},{outline:'0 solid transparent'}],{duration:1600});return}navigate('builder');if(el.dataset.entry){const chip=$(`[data-lesson="${el.dataset.entry}"]`);chip?.scrollIntoView({behavior:'smooth',block:'center',inline:'center'});chip?.animate([{outline:'4px solid #c64242'},{outline:'0 solid transparent'}],{duration:1600})}});
    $('#workloadBody').innerHTML=state.teachers.map(t=>{const n=state.schedule.filter(e=>e.teacherId===t.id).length,d=n-(Number(t.quota)||0);return `<tr><td>${esc(t.name)}</td><td>${esc(t.department)}</td><td>${t.quota||0}</td><td>${n}</td><td><span class="tag" style="color:${d===0?'var(--green)':d>0?'var(--red)':'var(--amber)'}">${d>0?'+':''}${d}</span></td></tr>`}).join('');
  }
  function teacherGaps(){let total=0;state.teachers.forEach(t=>activeDays().forEach(d=>{const a=state.schedule.filter(e=>e.teacherId===t.id&&e.dayId===d.id).map(e=>Number(e.periodId)).sort((x,y)=>x-y);if(a.length>1)total+=(a[a.length-1]-a[0]+1-a.length)}));return total}

