  function to24(v){if(!v)return'';let [h,m]=v.split(':').map(Number);if(h<7)h+=12;return `${String(h).padStart(2,'0')}:${String(m||0).padStart(2,'0')}`}
  function from24(v){if(!v)return'';let [h,m]=v.split(':').map(Number);if(h>12)h-=12;return `${h}:${String(m).padStart(2,'0')}`}
  function saveProfile(){const p=byId(state.settings.profiles,activeProfileEditId);if(!p)return;snapshot('قبل تعديل نظام التوقيت',true);p.name=$('#profileNameEdit').value.trim()||'نظام توقيت';p.note=$('#profileNoteEdit').value.trim();$$('[data-period-start]').forEach(x=>{const row=p.periods.find(v=>Number(v.n)===Number(x.dataset.periodStart));if(row)row.start=from24(x.value)});$$('[data-period-end]').forEach(x=>{const row=p.periods.find(v=>Number(v.n)===Number(x.dataset.periodEnd));if(row)row.end=from24(x.value)});p.breaks.forEach((b,i)=>{b.name=$(`[data-break-name="${i}"]`).value;b.after=Number($(`[data-break-after="${i}"]`).value);b.start=from24($(`[data-break-start="${i}"]`).value);b.end=from24($(`[data-break-end="${i}"]`).value)});p.periodCount=p.periods.length;save(true);renderAll();toast('تم حفظ نظام التوقيت المستقل.','success')}
  function addPeriod(){const p=byId(state.settings.profiles,activeProfileEditId);if(!p)return;snapshot();const last=p.periods[p.periods.length-1],start=(timeMinutes(last?.end)||450)+5,n=p.periods.length+1;p.periods.push({n,start:minutesTime(start),end:minutesTime(start+45)});p.periodCount=p.periods.length;save(true);renderProfiles();toast(`أضيفت الحصة ${n} إلى هذا النظام فقط.`,'success')}
