    const original=coreState(state),before=clone(state.schedule);snapshot('قبل تطبيق نظام توقيت جديد',true);if(scope==='classes'){state.classes.filter(c=>selectedClasses.has(c.id)).forEach(c=>{c.profileId=profile.id})}else{targets.forEach(d=>{state.settings.dayProfileIds[d]=profile.id;state.settings.dayPeriodCounts[d]=profile.periods.length});state.settings.periodCount=Math.max(...state.settings.days.map(d=>Number(state.settings.dayPeriodCounts[d])||1));state.settings.activeProfileId=profile.id}
    const capacity=scope==='classes'?state.settings.days.reduce((n,d)=>n+Math.min(profile.periods.length,Number(state.settings.dayPeriodCounts[d])||state.settings.periodCount),0):state.settings.days.reduce((n,d)=>n+(Number(state.settings.dayPeriodCounts[d])||0),0),counts=scaledAssignmentCounts(capacity);state.assignments.forEach(a=>{if(scope!=='classes'||selectedClasses.has(a.classId))a.weeklyCount=counts.get(a.id)??0});state.teachers.forEach(t=>{t.quota=state.assignments.filter(a=>a.teacherId===t.id).reduce((n,a)=>n+Number(a.weeklyCount||0),0)});
    const used=new Map();state.schedule=state.schedule.filter(e=>{const affected=scope!=='classes'||selectedClasses.has(e.classId);if(!affected)return true;const limit=Number(byId(state.assignments,e.assignmentId)?.weeklyCount)||0,n=used.get(e.assignmentId)||0,valid=state.settings.days.includes(e.dayId)&&Number(e.periodId)<=slotsForDay(e.dayId).length&&!placementConstraint(e);if(valid&&n<limit){used.set(e.assignmentId,n+1);return true}return false});state.schedule.forEach(e=>{e.locked=false});let result=generateBest(true),audit=computeAudit(result.schedule);if(result.missing||audit.hard.length){result=generateBest(false);audit=computeAudit(result.schedule)}
