  function saveSettings(){const days=$$('#daysSettings input:checked').map(x=>x.value);if(!days.length){toast('اختر يوم دوام واحدًا على الأقل.','error');return}snapshot('قبل حفظ إعدادات المدرسة',true);const markers=$$('[data-marker-row]').map(row=>{const o={id:row.dataset.id};$$('[data-marker-field]',row).forEach(x=>o[x.dataset.markerField]=x.dataset.markerField==='after'?Number(x.value):x.dataset.markerField==='start'||x.dataset.markerField==='end'?from24(x.value):x.value);return o}),footerItems=collectFooterItems();Object.assign(state.settings,{schoolName:$('#schoolNameInput').value.trim()||'مدرستي',academicYear:$('#academicYearInput').value.trim(),term:$('#termInput').value.trim(),issueDate:$('#issueDateInput').value||new Date().toISOString().slice(0,10),days,breakMarkers:markers,avoidLateEarly:$('#avoidLateEarly').checked,allowSoftBreak:$('#allowSoftBreak').checked});state.footerItems=footerItems;state.settings.principal=footerItems.find(x=>x.role==='principal')?.name||'';state.settings.coordinator=footerItems.find(x=>x.role==='coordinator')?.name||'';state.schedule=state.schedule.filter(e=>days.includes(e.dayId));Object.keys(state.settings.dayProfileIds).forEach(d=>{if(!days.includes(d))delete state.settings.dayProfileIds[d]});save(true);renderAll();toast('تم حفظ بيانات المدرسة والتاريخ والفواصل والتذييل.','success')}

