    const days=activeDays(),ps=slots(),dayColors=['#0f5f8b','#14796f','#5a62a5','#a96c14','#3e774b'];
    const w=1600,h=255+ps.length*105,c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);x.direction='rtl';x.textAlign='center';x.textBaseline='middle';
    x.fillStyle='#0d3154';x.font='bold 34px Tahoma';x.fillText(mode==='teacher'?`جدول المعلّم: ${entity.name}`:`جدول الفصل: ${entity.name}`,w/2,48);x.fillStyle='#53677a';x.font='20px Tahoma';x.fillText(`${state.settings.schoolName} • ${state.settings.term} • ${state.settings.academicYear}`,w/2,87);x.font='13px Tahoma';x.fillText(`تاريخ الإصدار: ${formatDateAr(state.settings.issueDate)}`,w/2,112);
