    days.forEach((d,di)=>{const xx=gridRight-(di+1)*cw;x.fillStyle=dayColors[di%dayColors.length];x.fillRect(xx,top,cw,55);x.strokeStyle='#fff';x.lineWidth=3;x.strokeRect(xx,top,cw,55);x.fillStyle='#fff';x.font='bold 18px Tahoma';x.fillText(d.name,xx+cw/2,top+28)});
    ps.forEach((p,ri)=>{const y=top+55+ri*rh;x.fillStyle='#e9f2f7';x.fillRect(timeX,y,timeW,rh);x.strokeStyle='#8fa4b4';x.lineWidth=1;x.strokeRect(timeX,y,timeW,rh);x.fillStyle='#173a5b';x.font='bold 17px Tahoma';x.fillText(`الحصة ${p}`,timeX+timeW/2,y+37);x.font='14px Tahoma';x.fillText(fmtTime(profile,p),timeX+timeW/2,y+66);days.forEach((d,di)=>{const xx=gridRight-(di+1)*cw,classLimit=mode==='class'?(profileFor(id,d.id)?.periods?.length||slotsForDay(d.id).length):slotsForDay(d.id).length,closed=p>Math.min(slotsForDay(d.id).length,classLimit);x.fillStyle=closed?'#edf1f4':di%2?'#fbfdfc':'#fff';x.fillRect(xx,y,cw,rh);x.strokeStyle='#8fa4b4';x.strokeRect(xx,y,cw,rh);const e=!closed&&state.schedule.find(e=>e.dayId===d.id&&Number(e.periodId)===p&&(mode==='teacher'?e.teacherId===id:e.classId===id));const special=!closed&&mode==='teacher'?specialFor(id,d.id,p):null;if(e){x.fillStyle=subjectColor(e.subjectId);x.fillRect(xx+5,y+5,cw-10,rh-10);x.fillStyle='#18344f';x.font='bold 18px Tahoma';x.fillText(subjectName(e.subjectId),xx+cw/2,y+39);x.font='15px Tahoma';x.fillText(mode==='teacher'?className(e.classId):teacherName(e.teacherId),xx+cw/2,y+68)}else if(special){x.fillStyle=special.color;x.fillRect(xx+5,y+5,cw-10,rh-10);x.fillStyle=special.type==='external'?'#4b4200':'#fff';x.font='bold 14px Tahoma';x.fillText(special.label,xx+cw/2,y+rh/2)}else if(closed){x.fillStyle='#7b8792';x.font='13px Tahoma';x.fillText('لا توجد حصة',xx+cw/2,y+rh/2)}x.strokeStyle=dayColors[di%dayColors.length];x.lineWidth=4;x.beginPath();x.moveTo(xx,y);x.lineTo(xx,y+rh);x.stroke()})});
